it('should transform APP_INITIALIZER + useFactory into provideAppInitializer', async () => {
    const content = await migrateCode(`
      import { APP_INITIALIZER } from '@angular/core';

      const providers = [{
        provide: APP_INITIALIZER,
        useFactory: () => {
          const service = inject(Service);
          return () => service.init();
        },
        multi: true,
      }];
    `);

    expect(content).toContain(`const providers = [provideAppInitializer(() => { return (() => {
          const service = inject(Service);
          return () => service.init();
        })(); })];`);
  });

  it('should transform APP_INITIALIZER + useExisting into provideAppInitializer', async () => {
    const content = await migrateCode(`
      import { APP_INITIALIZER } from '@angular/core';

      const providers = [{
        provide: APP_INITIALIZER,
        useExisting: MY_INITIALIZER,
        multi: true,
      }];
    `);

import {ApplicationConfig} from '@angular/core';
import {Logger} from './logger.service';
import {UserService} from './user.service';
import {APP_CONFIG, HERO_DI_CONFIG} from './injection.config';
import {provideProtractorTestingSupport} from '@angular/platform-browser';

const appConfig: ApplicationConfig = {
  providers: [
    provideProtractorTestingSupport(),
    Logger,
    UserService,
    {provide: APP_CONFIG, useValue: HERO_DI_CONFIG},
  ],
};

export default appConfig;

export interface AppConfig {
  title: string;
}

export const APP_CONFIG = new InjectionToken<AppConfig>('app.config description');
</docs-code>

The optional type parameter, `<AppConfig>`, and the token description, `app.config description`, specify the token's purpose.

Next, register the dependency provider in the component using the `InjectionToken` object of `APP_CONFIG`:

<docs-code header="src/app/app.component.ts" language="typescript">
const MY_APP_CONFIG_VARIABLE: AppConfig = {
  title: 'Hello',
};

providers: [{ provide: APP_CONFIG, useValue: MY_APP_CONFIG_VARIABLE }]
</docs-code>

Now, inject the configuration object into the constructor with the `@Inject()` parameter decorator:

<docs-code header="src/app/app.component.ts" language="typescript" highlight="[2]">
export class AppComponent {
  constructor(@Inject(APP_CONFIG) config: AppConfig) {
    this.title = config.title;
  }
}
</docs-code>

